mapper.select:
select
sec.Sec_Name as secName, c1.C_Name as dcConstruName, c2.C_Name as dcSuperviName, c3.C_Name as dcDesignName, c1.C_Abbreviation as dcConstruAbbName, c2.C_Abbreviation as dcSuperviAbbName, c3.C_Abbreviation as dcDesignAbbName, mn.* from Design_Completed mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on c1.C_Id=mn.Dc_Constru_Unit left join SYS_Company c2 on c2.C_Id=mn.Dc_Supervi_Unit left join SYS_Company c3 on c3.C_Id=mn.Dc_Design_Unit
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Dc_Create_Time desc
